import { generateBoard } from './deck.ts';
import { SelectionKind } from './selection.ts';
import type { Board } from './deck.ts';
import type { Selection } from './selection.ts';

export const ELAPSED_MAX_MS = 359_999_999;
export const MISMATCH_MS = 800;
export const MOVES_MAX = 999_999;

export interface GameState extends Board {
  readonly name: string;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState {
  return {
    ...generateBoard(boardCode),
    name: '',
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

// The board reads one set per game state instead of searching the matched list for every card.
export function faceUpCards(state: Pick<GameState, 'matched' | 'selection'>): ReadonlySet<number> {
  const cards = new Set(state.matched);
  const selection = state.selection;
  if (selection.kind === SelectionKind.one) cards.add(selection.index);
  if (selection.kind === SelectionKind.mismatch) {
    cards.add(selection.first);
    cards.add(selection.second);
  }
  return cards;
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length) return state;
  if (state.matched.includes(index)) return state;
  switch (state.selection.kind) {
    case SelectionKind.closed:
      return { ...state, started: true, selection: { kind: SelectionKind.one, index } };
    case SelectionKind.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MOVES_MAX, state.moves + 1);
      if (state.deck[first] === state.deck[index]) {
        return {
          ...state,
          moves,
          matched: [...state.matched, first, index],
          selection: { kind: SelectionKind.closed },
        };
      }
      return {
        ...state,
        moves,
        selection: { kind: SelectionKind.mismatch, first, second: index, remainingMs: MISMATCH_MS },
      };
    }
    case SelectionKind.mismatch:
      return state;
    default:
      return unreachable(state.selection);
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0) return state;
  if (!state.started || isWon(state)) return state;
  const elapsedMs = Math.min(ELAPSED_MAX_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== SelectionKind.mismatch) return { ...state, elapsedMs };
  const remainingMs = state.selection.remainingMs - milliseconds;
  const selection =
    remainingMs > 0 ? { ...state.selection, remainingMs } : { kind: SelectionKind.closed };
  return { ...state, elapsedMs, selection };
}

function unreachable(value: never): never {
  throw new Error(`Unknown selection: ${String(value)}`);
}
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { createGame, activateCard, advanceGame } from './game.ts';
import { DEAL_NAME_MAX_LENGTH, isValidDealName, renameGame } from './deal-name.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from './game.fixture.ts';

test('deal names preserve spaces and Unicode within forty UTF-16 code units', () => {
  assert.equal(DEAL_NAME_MAX_LENGTH, 40);
  for (const name of [
    '',
    ' ',
    '  Café  ',
    '\t\u0000\u2028\u2029',
    'x'.repeat(40),
    '😀'.repeat(20),
  ]) {
    assert.equal(isValidDealName(name), true);
    assert.equal(renameGame(createGame(EXAMPLE_CODE), name).name, name);
  }
  for (const name of ['x'.repeat(41), '😀'.repeat(21), 'a\rb', 'a\nb', '\r\n']) {
    const state = renameGame(createGame(EXAMPLE_CODE), 'Original');
    assert.equal(isValidDealName(name), false);
    assert.equal(renameGame(state, name), state);
  }
  for (const value of [null, undefined, 1, true, [], {}])
    assert.equal(isValidDealName(value), false);
});

test('naming and clearing progress change only its name throughout play', () => {
  const initial = createGame(EXAMPLE_CODE);
  assert.equal(initial.name, '');
  const first = activateCard(initial, 0);
  const pending = advanceGame(activateCard(first, 1), 0.75);
  let completed = initial;
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) completed = activateCard(completed, index);
  for (const state of [initial, first, pending, completed]) {
    const named = renameGame(state, '  Café  ');
    assert.deepEqual(named, { ...state, name: '  Café  ' });
    assert.equal(state.name, '');
    assert.equal(renameGame(named, named.name), named);
    assert.deepEqual(renameGame(named, ''), state);
  }
});

test('card actions and active time retain the deal name', () => {
  const named = renameGame(createGame(EXAMPLE_CODE), 'Café');
  const first = activateCard(named, 0);
  const mismatch = activateCard(first, 1);
  const elapsed = advanceGame(mismatch, 800);
  const match = activateCard(activateCard(elapsed, 2), 6);
  for (const state of [first, mismatch, elapsed, match]) assert.equal(state.name, 'Café');
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { createGame, activateCard, advanceGame, isWon } from './game.ts';
import { renameGame } from './deal-name.ts';
import {
  decodeSnapshot,
  encodeSnapshot,
  NAMED_SNAPSHOT_VERSION,
  SNAPSHOT_KEYS,
  SNAPSHOT_MAX_BYTES,
  SNAPSHOT_VERSION,
} from './snapshot.ts';
import { SelectionKind } from './selection.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from './game.fixture.ts';
import { isJsonObject } from './saved-format.ts';

const NAMED = {
  version: NAMED_SNAPSHOT_VERSION,
  name: 'Café',
  boardCode: EXAMPLE_CODE,
  matched: [],
  selection: { kind: SelectionKind.one, index: 2 },
  moves: 0,
  elapsedMs: 0,
  started: true,
};

test('named and unnamed progress round trip using their exact versioned fields', () => {
  assert.equal(NAMED_SNAPSHOT_VERSION, 2);
  const start = createGame(EXAMPLE_CODE);
  const one = activateCard(start, 0);
  const mismatch = advanceGame(activateCard(one, 1), 175);
  let completed = start;
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) completed = activateCard(completed, index);
  assert.equal(isWon(completed), true);
  for (const progress of [start, one, mismatch, completed])
    for (const name of ['Café', '  Café  ', ' ', '😀'.repeat(20)]) {
      const named = renameGame(progress, name);
      const text = encodeSnapshot(named);
      const exported: unknown = JSON.parse(text);
      assert.ok(isJsonObject(exported));
      assert.deepEqual(Object.keys(exported).sort(), [...SNAPSHOT_KEYS, 'name'].sort());
      assert.equal(exported.version, NAMED_SNAPSHOT_VERSION);
      assert.deepEqual(decodeSnapshot(text), {
        ...named,
        matched: [...named.matched].sort((left, right) => left - right),
      });
      const unnamed = renameGame(named, '');
      const legacy: unknown = JSON.parse(encodeSnapshot(unnamed));
      assert.ok(isJsonObject(legacy));
      assert.deepEqual(Object.keys(legacy).sort(), [...SNAPSHOT_KEYS].sort());
      assert.equal(legacy.version, SNAPSHOT_VERSION);
      assert.equal(decodeSnapshot(encodeSnapshot(unnamed))?.name, '');
    }
});

test('named imports accept reordered fields and keep the specification example progress', () => {
  const expected = { ...activateCard(createGame(EXAMPLE_CODE), 2), name: 'Café' };
  const fields = Object.entries(NAMED);
  for (let offset = 0; offset < fields.length; offset++) {
    const rotated = [...fields.slice(offset), ...fields.slice(0, offset)];
    for (const entries of [rotated, [...rotated].reverse()])
      assert.deepEqual(decodeSnapshot(JSON.stringify(Object.fromEntries(entries))), expected);
  }
});

test('named imports reject invalid names, unsupported versions and inconsistent progress', () => {
  for (const overrides of [
    ...['', 'x'.repeat(41), '😀'.repeat(21), 'a\rb', 'a\nb', '\r\n', null, 1, [], {}].map(
      (name) => ({ name }),
    ),
    ...[SNAPSHOT_VERSION, 0, 3, '2', null].map((version) => ({ version })),
    { extra: true },
    { moves: -1 },
    { elapsedMs: 359_999_999 + 1 },
    { started: false },
    { matched: [2] },
    { selection: { kind: SelectionKind.one, index: 16 } },
  ])
    assert.equal(decodeSnapshot(JSON.stringify({ ...NAMED, ...overrides })), null);
  const fields = Object.entries(NAMED);
  for (const [missing] of fields)
    assert.equal(
      decodeSnapshot(JSON.stringify(Object.fromEntries(fields.filter(([key]) => key !== missing)))),
      null,
    );
});

test('named snapshot limits count UTF-8 bytes including the name', () => {
  const text = JSON.stringify({ ...NAMED, name: '😀'.repeat(20) });
  const padding = ' '.repeat(SNAPSHOT_MAX_BYTES - Buffer.byteLength(text, 'utf8'));
  assert.ok(decodeSnapshot(text + padding));
  assert.equal(decodeSnapshot(text + padding + ' '), null);
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { decodeSnapshot, SNAPSHOT_VERSION } from './snapshot.ts';
import { SelectionKind } from './selection.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';

const SNAPSHOT = {
  version: SNAPSHOT_VERSION,
  boardCode: EXAMPLE_CODE,
  matched: [],
  selection: { kind: SelectionKind.closed },
  moves: 0,
  elapsedMs: 0,
  started: false,
};

test('snapshot fields can appear in every position without changing restored progress', () => {
  const expected = decodeSnapshot(JSON.stringify(SNAPSHOT));
  assert.ok(expected, 'valid baseline');
  const fields = Object.entries(SNAPSHOT);
  for (let offset = 0; offset < fields.length; offset++) {
    const rotated = [...fields.slice(offset), ...fields.slice(0, offset)];
    for (const entries of [rotated, [...rotated].reverse()])
      assert.deepEqual(decodeSnapshot(JSON.stringify(Object.fromEntries(entries))), expected);
  }
});

test('selection fields accept reversed order and top-level fields remain exact', () => {
  for (const selection of [
    { kind: SelectionKind.closed },
    { kind: SelectionKind.one, index: 0 },
    { kind: SelectionKind.mismatch, first: 0, second: 1, remainingMs: 300 },
  ]) {
    const progress = { ...SNAPSHOT, started: true, moves: 1, selection };
    const reversed = Object.fromEntries(Object.entries(selection).reverse());
    const restored = decodeSnapshot(JSON.stringify({ ...progress, selection: reversed }));
    assert.ok(restored);
    assert.deepEqual(restored.selection, selection);
  }
  const fields = Object.entries(SNAPSHOT);
  for (const [missing] of fields)
    assert.equal(
      decodeSnapshot(JSON.stringify(Object.fromEntries(fields.filter(([key]) => key !== missing)))),
      null,
    );
  for (const key of ['extra', 'name', '__proto__'])
    assert.equal(
      decodeSnapshot(JSON.stringify(Object.fromEntries([...fields, [key, 'unexpected']]))),
      null,
    );
});
export function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function isNonnegativeSafeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

export function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return (
    Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
  );
}

export function isWithinBytes(text: string, maxBytes: number): boolean {
  return new TextEncoder().encode(text).byteLength <= maxBytes;
}

// No JSON text parses to undefined, so it marks malformed input.
export function parseJson(text: string): unknown {
  try {
    const value: unknown = JSON.parse(text);
    return value;
  } catch {
    return undefined;
  }
}
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from './saved-format.ts';
import { MISMATCH_MS } from './game.ts';
import { SelectionKind, type Selection } from './selection.ts';
import type { GameState } from './game.ts';

export function readSelection(
  value: unknown,
  state: GameState,
  matched: readonly number[],
): Selection | null {
  if (!isJsonObject(value)) return null;
  const available = (index: unknown): index is number =>
    isNonnegativeSafeInteger(index) && index < state.deck.length && !matched.includes(index);
  switch (value.kind) {
    case SelectionKind.closed:
      return hasExactKeys(value, ['kind']) ? { kind: SelectionKind.closed } : null;
    case SelectionKind.one:
      return hasExactKeys(value, ['kind', 'index']) && available(value.index)
        ? { kind: SelectionKind.one, index: value.index }
        : null;
    case SelectionKind.mismatch:
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null;
      if (!available(value.first) || !available(value.second) || value.first === value.second)
        return null;
      if (state.deck[value.first] === state.deck[value.second]) return null;
      if (
        !isNonnegativeSafeInteger(value.remainingMs) ||
        value.remainingMs < 1 ||
        value.remainingMs > MISMATCH_MS
      )
        return null;
      return {
        kind: SelectionKind.mismatch,
        first: value.first,
        second: value.second,
        remainingMs: value.remainingMs,
      };
    default:
      return null;
  }
}

export function readMatched(value: unknown, state: GameState): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const matched: number[] = [];
  const counts = new Map<number, number>();
  for (const index of value) {
    if (!isNonnegativeSafeInteger(index) || index >= state.deck.length || matched.includes(index))
      return null;
    const face = state.deck[index];
    if (face === undefined) return null;
    matched.push(index);
    counts.set(face, (counts.get(face) ?? 0) + 1);
  }
  return [...counts.values()].every((count) => count === 2) ? matched : null;
}

import { expect, test } from './browser-test.ts';
